  "x_brassroof": { "n": "Звенящая комната под латунной крышей", "era": "I", "desc": "Круглая комната «Колыбели», где стены звенят от шагов, накрыта сверху латунной крышей Механизма: шестерни в своде медленно проворачиваются и подхватывают звон. Пахнет тёплой медью и речной водой.", "obj": {"shelf":0.5,"crate":0.3}, "fx": {"gears":0.7,"bell":0.6}, "loot": "tech", "sign": "Ступать мягко: стены слушают", "size": [4,4] },
  "x_layeredsound": { "n": "Комната слоёного звука", "era": "I", "desc": "Звук здесь лежит слоями, как ил на дне: у самого пола — гул сорокалетней давности, на уровне колен — вчерашние шаги, у груди — свежие голоса. Воздух на разной высоте разный на ощупь: внизу плотный и прохладный, вверху тёплый и лёгкий.", "obj": {"crate":0.4}, "fx": {"echo":0.8,"horns":0.6}, "loot": "tech", "sign": "Слои не перемешивать", "size": [4,4] },
