  "x_reactorhive": { "n": "Пасека у реактора", "era": "I", "rad": 1, "desc": "Ульи стоят вплотную к тёплой стене, за которой гудит настоящий реактор, и механические пчёлы здесь не знают зимы. Мёд у них густой, с привкусом металла, а гул ульев и гул реактора сливаются в один низкий звук.", "obj": {"shelf":0.7,"crate":0.4}, "fx": {"beehive":1,"gauges":0.5}, "loot": "food", "owner": "пасечник", "sign": "Пасека. Фон повышен: не задерживаться", "size": [4,4] },
  "x_appledry": { "n": "Сушильня яблок", "era": "I", "desc": "Над тёплыми трубами натянуты нитки с яблочными дольками, и вся сушильня пахнет так сладко, что хочется зажмуриться. Готовые дольки шуршат в мешках на полках, а у печи стоят решёта с новой партией.", "obj": {"shelf":0.8,"crate":0.5}, "fx": {"oven":1}, "loot": "food", "owner": "сушильщик", "sign": "Сушильня. До хруста не трогать", "size": [4,4] },
  "x_knotroom": { "n": "Комната отвечающих узлов", "era": "I", "desc": "Под сводом натянуты верёвки с узелками, и каждый узел, если его тронуть, отвечает своим звуком: то плеском, то лаем, то чьим-то словом. Так здесь записывали дороги и память, и по узлам можно пальцами пройти весь этаж.", "obj": {}, "fx": {"soundmap":1}, "loot": "paper", "sign": "Узлы не развязывать", "size": [4,4] },
  "x_lastlodging": { "n": "Ночлег последних людей", "era": "I", "desc": "Здесь ночуют последние люди, дошедшие так глубоко: койки в два ряда, одеяла из старых ватников, чайник на тёплой трубе. Над дверью табличка: «Свободная койка — всегда для того, кто придёт после».", "obj": {"locker":0.6,"capsule":0.3}, "fx": {"bunk":1,"kettle":1}, "loot": "home", "owner": "староста ночлега", "sign": "Ночлег. Говорить тише", "size": [5,5], "safe": true },
  "x_shelltools": { "n": "Склад инструментов из гильз", "era": "I", "desc": "Здесь из стреляных гильз делают садовый инструмент: лейки, совки, колокольчики, набойки для мотыг. Гильзы — от мортир машин и сейсмических зарядов «Глубины» — рассортированы по ящикам, на щите висят готовые вещи, и пахнет латунью и окалиной.", "obj": {"crate":0.9,"shelf":0.7,"locker":0.4}, "fx": {"toolwall":1}, "loot": "parts", "owner": "жестянщик", "sign": "Гильзы — сюда. Оружие — не сюда", "size": [4,4] },
  "x_circletime": { "n": "Комната, где время идёт по кругу", "era": "I", "desc": "Время в этой комнате бежит по кругу длиной в несколько минут: чайник закипает, остывает и закипает снова, а маятник возвращается туда, откуда качнулся. На стене процарапано: «Не задерживаться дольше одного круга — потом трудно выйти».", "obj": {"desk":0.4,"shelf":0.4}, "fx": {"kettle":1,"pendulum":1,"clock":0.6}, "loot": "tech", "sign": "Один круг — и дальше", "size": [4,4] }
