  "x_radiohut": [
    { "e": "K", "n": "Радиорубка связи с поверхностью", "d": "Рация с длинной антенной, уходящей в потолок, стоит у стены, а рядом висят наушники, в которых сквозь треск иногда прорывается голос: «Карантин, ответьте». Стул придвинут вплотную к рации, и на его спинке висит свитер, пропахший кофе.", "fx": {"headphones":0.9,"chair":0.8} },
    { "e": "K", "n": "Рубка громкой связи", "d": "На пульте громкой связи — микрофон на гибкой ножке и ряд тумблеров с названиями коридоров, на крючке — наушники дежурного. Объявления давно ведёт ОКО, и из маленького динамика на пульте каждые полчаса доносится ровный голос: «Сохраняйте спокойствие».", "fx": {"headphones":0.9} },
    { "e": "K", "n": "Радиорубка ремонтных бригад", "d": "Вдоль стены — гнёзда зарядки для раций, и в трёх из них рации до сих пор помигивают, полные заряда и никому не нужные. На стене — список позывных, где у каждой бригады своё прозвище: «Гайка», «Сварка», «Кот в сапогах».", "fx": {"headphones":0.7,"chair":0.6} },
    { "e": "K", "n": "Пост прослушивания эфира", "d": "Шум глубины слушали в этой рубке: приёмник настроен на пустую частоту, и в наушниках вместо голосов идёт ровный низкий гул, похожий на пение. На стуле лежит блокнот, где кто-то записывал этот гул нотами, страница за страницей.", "fx": {"headphones":0.9,"chair":0.8} },
    { "e": "P", "n": "Радиоузел городка", "d": "Отсюда в каждую квартиру городка шла радиоточка: у стены — ламповый усилитель, всё ещё тёплый на ощупь, и микрофон, обмотанный изолентой, а на крючке — наушники диктора. На стене — расписание передач: утренняя зарядка, новости горизонтов и концерт по заявкам.", "fx": {"headphones":0.9} },
    { "e": "P", "n": "Радиорубка буровой", "d": "Рация в железном корпусе связывала буровую с поверхностью, и её позывной выбит прямо на кожухе: «Глубина-первая». Наушники висят на гвозде, а в эфире шипит так ровно, будто кто-то на том конце затаил дыхание.", "fx": {"headphones":0.9,"chair":0.6} },
    { "e": "P", "n": "Студия радиогазеты профкома", "d": "Стены обиты войлоком, чтобы не было эха, и голос здесь звучит глухо, как в шкафу с шубами. На подставке — микрофон с решёткой, похожей на тёрку, а на стуле лежит стопка листков с текстом выпуска: «Сегодня в клубе — вечер хора, приходите семьями».", "fx": {"chair":0.9,"headphones":0.6} },
    { "e": "P", "n": "Радиопост сейсмической службы", "d": "Приёмник здесь слушал не голоса, а землю: в наушниках щёлкают сигналы с дальних датчиков, по одному на каждый толчок. Рядом на тумбе — самописец под колпаком, и его перо вздрагивает в такт щелчкам.", "fx": {"headphones":0.9,"seismograph":0.8} }
  ],
